const path = require('path');

const { getDefaultConfig } = require('expo/metro-config');

/** @type {import('expo/metro-config').MetroConfig} */
const config = getDefaultConfig(__dirname);

// Database migrations are plain .sql files generated by drizzle-kit.
config.resolver.sourceExts.push('sql');

// The server lives in the same repository but is never part of the app bundle.
// Block exactly <project>/server/..., whichever slash the operating system uses.
const escapeRegExp = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const serverFolder = path
  .resolve(__dirname, 'server')
  .split(/[\\/]/)
  .map(escapeRegExp)
  .join('[\\\\/]');
config.resolver.blockList = [new RegExp(`^${serverFolder}[\\\\/]`)];

module.exports = config;
